import Kit

/// The data file's text. `EmojiData.swift` is generated by `Tools/generate-data.py`.
nonisolated enum EmojiData {}

/// Every emoji and symbol, in the order of the grid, with lookups by key.
nonisolated struct EmojiCatalog: Sendable {
    let entries: [EmojiEntry]
    private let positions: [String: Int]

    init(entries: [EmojiEntry]) {
        self.entries = entries
        positions = Dictionary(entries.enumerated().map { ($1.key, $0) }) { first, _ in first }
    }

    /// The position of the entry with this key.
    func position(ofKey key: String) -> Int? {
        positions[key]
    }

    /// The entry with this key.
    func entry(forKey key: String) -> EmojiEntry? {
        positions[key].map { entries[$0] }
    }

    /// Parses data in the generator's format: one entry per line,
    /// `glyph;name;group;version;common rank;keywords;skin tone variants`.
    static func parse(_ text: String) throws -> EmojiCatalog {
        var entries: [EmojiEntry] = []
        entries.reserveCapacity(2_800)
        var lineNumber = 0
        for line in text.utf8.split(separator: UInt8(ascii: "\n")) {
            lineNumber += 1
            let fields = line.split(separator: UInt8(ascii: ";"), omittingEmptySubsequences: false)
            guard fields.count == 7, !fields[0].isEmpty, !fields[1].isEmpty,
                let groupNumber = Int(Self.string(fields[2])), let group = EmojiGroup(rawValue: groupNumber),
                let commonRank = Int(Self.string(fields[4]))
            else { throw EmojiDataError(line: lineNumber) }
            let keywords = fields[5].split(separator: UInt8(ascii: "|")).map(Self.string)
            let variants = fields[6].split(separator: UInt8(ascii: " ")).map(Self.string)
            guard variants.isEmpty || variants.count == 5 || variants.count == 25 else {
                throw EmojiDataError(line: lineNumber)
            }
            entries.append(
                EmojiEntry(
                    glyph: Self.string(fields[0]), name: Self.string(fields[1]), group: group,
                    version: Self.string(fields[3]), commonRank: commonRank, keywords: keywords, variants: variants))
        }
        return EmojiCatalog(entries: entries)
    }

    private static func string(_ bytes: Substring.UTF8View.SubSequence) -> String {
        String(decoding: bytes, as: UTF8.self)
    }
}

/// The data file has a line the parser does not understand.
nonisolated struct EmojiDataError: Error, Hashable {
    let line: Int
}
